use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";
const HEX: &[u8; 16] = b"0123456789ABCDEF";

/// Percent-encode every byte outside the RFC 3986 unreserved set, so the input
/// text cannot change the URL's host, path, or query structure.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // "The input's text": PublishedDigest has no text field, so the text is
        // its full content in a fixed form: date, published flag, considered ids.
        // Assumption: this is the intended meaning of "the input's text".
        let text = format!(
            "{}|{}|{}",
            published.date,
            published.published,
            published.considered.join(",")
        );
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&text));

        // Enrichment is fetched on every call before any state is written, so a
        // refused request (a trap at the boundary) aborts before the store changes.
        // The result is discarded and a transport failure is a value, so the
        // output is unchanged either way.
        let _ = http_client::fetch(&url);

        // Mark every considered item as seen. Ids are parser-computed digests,
        // so they are safe as store keys. Count only the ids newly recorded.
        let mut recorded: u32 = 0;
        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
